import { exceptions } from "../constants";
import { logger } from "../helper";
import { decrypt } from "./aes"

/**
 * Decrypt data function.
 * @param {string} hVal - Encryption key for decrypt data.
 * @param {any} payload - Encrypted data.
 * @param {string} responseType - Response type JSON/STRING.
 * @returns {Promise<any>} A promise that resolves to the decrypt data.
 */
export const decryptPayload = async (hVal: string, payload: any, responseType: string, logging: boolean): Promise<any> => {
  try {
    logger(logging, "Payload for decryption", payload);
    logger(logging, "Key for decryption", hVal);

    const response = payload.data;

    let decryptedResp: any = {
      status: response.status,
      data: []
    };

    const payloadDetails = response.data[0].encryptedResponse || response.data[0];
    let decryptedPayload = await decrypt(hVal, payloadDetails);
    if(response.count && response.total) {
      decryptedPayload = `{"data": ${decryptedPayload}, "count": ${response.count}, "total": ${response.total}}`;
    }
    decryptedResp.data.push((responseType == "STRING")?decryptedPayload:JSON.parse(decryptedPayload));
    logger(logging, "Decryption response", decryptedResp);
    return decryptedResp;
  } catch (error: any) {
    logger(logging, "Decryption error:", error);
    throw {data: { errors: [{
      errorCode: exceptions.decryptionErrorCode,
      errorMessage: exceptions.decryptionErrorMessage
    }]}};
  }
}
