/**
 * Orders resource.
 * This class handles all interactions with the /orders API endpoint.
 */
import { AxiosInstance } from 'axios';
import { OrderEntity, OrderSearchEntity, ResponseEntity } from '../types';
import { Api } from '../utils/services';
import { logger, sbiException } from '../utils/helper';
import { errors, exceptions, logTitles } from '../utils/constants';
import { endpoints } from '../utils/endpoints';

export class Order extends Api {
  /**
   * Creates an instance of the Order.
   * @param {AxiosInstance} apiClient - Axios instance for API handle.
   * @param {string} encryptionKey - Encryption key for handle request/response encryption/decryption.
   * @param {boolean} logging - Enable/Disable API logs.
   * @param {string} responseType - Data convert to JSON/Stringify enable/disable.
   */
  constructor(apiClient: AxiosInstance, encryptionKey: string, logging: boolean, responseType: string) {
    super(apiClient, encryptionKey, logging, responseType);
  }

  /**
   * Creates a new order.
   * @param {any} payload - The data for creating the order.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the created order entity.
   */
  async create(payload: any): Promise<ResponseEntity> {
    if (!payload) {
      logger(this.logging, logTitles.orderCreateError, errors.orderPayloadError);
      const data = { error: errors.orderPayloadError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }
    
    try {
      const order = await this._post(endpoints.orderCreate, payload);
      logger(this.logging, logTitles.orderCreateSuccess, order);
      return order;
    } catch (error: any) {
      logger(this.logging, logTitles.orderCreateError, error);
      throw error;
    }
  }

  /**
   * Search orders by search payload.
   * @param {any} payload - The search payload of the order.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the fetched order entity.
   */
  async search(payload: any): Promise<ResponseEntity> {
    if (!payload) {
      logger(this.logging, logTitles.orderSearchError, errors.orderSearchError);
      const data = { error: errors.orderSearchError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    try {
      const order = await this._post(endpoints.orderSearch, payload);
      logger(this.logging, logTitles.orderSearchSuccess, order);
      return order;
    } catch (error: any) {
      logger(this.logging, logTitles.orderSearchError, error);
      throw error;
    }
  }

  /**
   * Search order by settled order by search payload.
   * @param {any} payload - The search payload of the order.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the fetched order entity.
   */
  async settledOrders(payload: any, page: number = 0, size: number = 50): Promise<ResponseEntity> {
    if (!payload) {
      logger(this.logging, logTitles.orderSettledError, errors.ordersettledPayloadError);
      const data = { error: errors.ordersettledPayloadError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }
    
    try {
      let payld;
      if(typeof payload !== "string") {
        payld = payload;
      } else {
        payld = JSON.parse(payload);
      }
      payld.settlementStatus = "SETTLED";
      
      const order = await this._post(`${endpoints.mis}?page=${page}&size=${size}`, payld);
      logger(this.logging, logTitles.orderSettledSuccess, order);
      return order;
    } catch (error: any) {
      logger(this.logging, logTitles.orderSettledError, error);
      throw error;
    }
  }

  /**
   * Search order by transaction success by search payload.
   * @param {any} payload - The search payload of the order.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the fetched order entity.
   */
  async transactionOrders(payload: any, page: number = 0, size: number = 50): Promise<ResponseEntity> {
    if (!payload) {
      logger(this.logging, logTitles.orderTransactionOrdersError, errors.orderTransactionOrdersPayloadError);
      const data = { error: errors.orderTransactionOrdersPayloadError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    try {
      const order = await this._post(`${endpoints.mis}?page=${page}&size=${size}`, payload);
      logger(this.logging, logTitles.orderTransactionOrdersSuccess, order);
      return order;
    } catch (error: any) {
      logger(this.logging, logTitles.orderTransactionOrdersError, error);
      throw error;
    }
  }
}
