import { exceptions } from "../constants";
import { logger } from "../helper";
import { encrypt } from "./aes";

/**
 * Encrypt data function.
 * @param {string} hVal - Encryption key for decrypt data.
 * @param {any} payload - Decrypted data.
 * @returns {Promise<any>} A promise that resolves to the encrypt data.
 */
export const encryptPayload = async (hVal: string, payload: any, logging: boolean): Promise<any> => {
  try {
    logger(logging, "Payload for encryption", payload);
    logger(logging, "Key for encryption", hVal);

    const encryptPayload = await encrypt(hVal, (typeof payload !== "string")?JSON.stringify(payload):payload);
    const encryptedPayload = {
      encryptedRequest: encryptPayload
    };
    logger(logging, "Encryption response", encryptedPayload);
    return encryptedPayload;
  } catch (error: any) {
    logger(logging, "Encryption error:", error);
    throw {data: {errors: [{
      errorCode: exceptions.encryptionErrorCode,
      errorMessage: exceptions.encryptionErrorMessage
    }]}};
  }
}
