/**
 * customers resource.
 * This class handles all interactions with the /customers API endpoint.
 */
import { AxiosInstance } from 'axios';
import { CustomerEntity, ResponseEntity } from '../types';
import { Api } from '../utils/services';
import { logger, sbiException } from '../utils/helper';
import { errors, exceptions, logTitles } from '../utils/constants';
import { endpoints } from '../utils/endpoints';

export class Customer extends Api {
  /**
   * Creates an instance of the Customer.
   * @param {AxiosInstance} apiClient - Axios instance for API handle.
   * @param {string} encryptionKey - Encryption key for handle request/response encryption/decryption.
   * @param {boolean} logging - Enable/Disable API logs.
   * @param {string} responseType - Data convert to JSON/Stringify enable/disable.
   */
  constructor(apiClient: AxiosInstance, encryptionKey: string, logging: boolean, responseType: string) {
    super(apiClient, encryptionKey, logging, responseType);
  }

  /**
   * Creates a new customer.
   * @param {any} payload - The data for creating the customer.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the created customer entity.
   */
  async create(payload: any): Promise<ResponseEntity> {
    if (!payload) {
      logger(this.logging, logTitles.customerCreateError, errors.customerPayloadError);
      const data = { error: errors.customerPayloadError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }
    
    try {
      const customer = await this._post(endpoints.customerCreate, payload);
      logger(this.logging, logTitles.customerCreateSuccess, customer);
      return customer;
    } catch (error: any) {
      logger(this.logging, logTitles.customerCreateError, error);
      throw error;
    }
  }

  /**
   * Fetches a specific customer by its ID.
   * @param {string} customerId - The unique identifier of the customer.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the fetched customer entity.
   */
  async get(customerId: string): Promise<ResponseEntity> {
    if (!customerId) {
      logger(this.logging, logTitles.customerFetchError, errors.customerIdError);
      const data = { error: errors.customerIdError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    try {
      const custId = encodeURIComponent(customerId);
      const customer = await this._get(`${endpoints.customer}/${custId}`);
      logger(this.logging, logTitles.customerFetchSuccess, customer);
      return customer;
    } catch (error: any) {
      logger(this.logging, logTitles.customerFetchError, error);
      throw error;
    }
  }

  /**
   * Update status of a specific customer by its ID.
   * @param {string} customerId - The unique identifier of the customer.
   * @param {string} status - The status of the customer.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the update customer entity.
   */
  private async updateStatus(customerId: string, status: 'ACTIVE' | 'INACTIVE' | 'DELETE'): Promise<ResponseEntity> {
    try {
      const customer = await this._post(`${endpoints.customer}/${customerId}/${status}`);
      logger(this.logging, logTitles.customerUpdateSuccess, customer);
      return customer;
    } catch (error: any) {
      logger(this.logging, logTitles.customerUpdateError, error);
      throw error;
    }
  }

  /**
   * Activate specific customer by its ID.
   * @param {string} customerId - The unique identifier of the customer.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the Activate customer entity.
   */
  async active(customerId: string): Promise<ResponseEntity> {
    if (!customerId) {
      logger(this.logging, logTitles.customerUpdateError, errors.customerIdError);
      const data = { error: errors.customerIdError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    try {
      return this.updateStatus(customerId, "ACTIVE");
    } catch (error: any) {
      throw error;
    }
  }

  /**
   * Inactivate specific customer by its ID.
   * @param {string} customerId - The unique identifier of the customer.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the Inactivate customer entity.
   */
  async inactive(customerId: string): Promise<ResponseEntity> {
    if (!customerId) {
      logger(this.logging, logTitles.customerUpdateError, errors.customerIdError);
      const data = { error: errors.customerIdError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    try {
      return this.updateStatus(customerId, "INACTIVE");
    } catch (error: any) {
      throw error;
    }
  }

  /**
   * Delete specific customer by its ID.
   * @param {string} customerId - The unique identifier of the customer.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the Delete customer entity.
   */
  async delete(customerId: string): Promise<ResponseEntity> {
    if (!customerId) {
      logger(this.logging, logTitles.customerUpdateError, errors.customerIdError);
      const data = { error: errors.customerIdError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    try {
      return this.updateStatus(customerId, "DELETE");
    } catch (error: any) {
      throw error;
    }
  }
}
