/**
 * Refunds resource.
 * This class handles all interactions with the /refunds API endpoint.
 */
import { AxiosInstance } from 'axios';
import { RefundEntity, RefundSearchEntity, ResponseEntity } from '../types';
import { Api } from '../utils/services';
import { logger, sbiException } from '../utils/helper';
import { errors, exceptions, logTitles } from '../utils/constants';
import { endpoints } from '../utils/endpoints';

export class Refund extends Api {
  /**
   * Creates an instance of the Refund.
   * @param {AxiosInstance} apiClient - Axios instance for API handle.
   * @param {string} encryptionKey - Encryption key for handle request/response encryption/decryption.
   * @param {boolean} logging - Enable/Disable API logs.
   * @param {string} responseType - Data convert to JSON/Stringify enable/disable.
   */
  constructor(apiClient: AxiosInstance, encryptionKey: string, logging: boolean, responseType: string) {
    super(apiClient, encryptionKey, logging, responseType);
  }

  /**
   * Book a refund.
   * @param {any} payload - The data for book refund.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the created refund entity.
   */
  async book(payload: any): Promise<ResponseEntity> {
    if (!payload) {
      logger(this.logging, logTitles.refundBookError, errors.refundPayloadError);
      const data = { error: errors.refundPayloadError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    try {
      const refund = await this._post(endpoints.refundBook, payload);
      logger(this.logging, logTitles.refundBookSuccess, refund);
      return refund;
    } catch (error: any) {
      logger(this.logging, logTitles.refundBookError, error);
      throw error;
    }
  }

  /**
   * Fetches a specific refund by its ID.
   * @param {any} payload - The payload of the refund.
   * @param {number} page - pagination page number.
   * @param {number} size - pagination page contain number of rows.
   * @returns {Promise<ResponseEntity>} A promise that resolves to the fetched refund entity.
   */
  async search(payload: any, page: number = 0, size: number = 50): Promise<ResponseEntity> {
    if (!payload) {
      logger(this.logging, logTitles.refundSearchError, errors.refundSearchError);
      const data = { error: errors.refundSearchError };
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }
    
    try {
      const refund = await this._post(`${endpoints.refundSearch}?page=${page}&size=${size}`, payload);
      logger(this.logging, logTitles.refundSearchSuccess, refund);
      return refund;
    } catch (error: any) {
      logger(this.logging, logTitles.refundSearchError, error);
      throw error;
    }
  }
}
