/**
 * API resource.
 * This class handles all interactions with the API methods.
 */
import { AxiosInstance } from 'axios';
import { encryptPayload } from './crypto/encryption';
import { decryptPayload } from './crypto/decryption';
import { AccessToken } from '../modules/AccessToken';
import { ResponseEntity } from '../types';
import { errors, exceptions, logTitles } from './constants';
import { logger, sbiException } from './helper';

export class Api {
    private api: AxiosInstance;
    private accessToken: AccessToken;
    private encryptionKey: string;
    protected logging: boolean;
    protected responseType: string;

    /**
     * Creates an instance of the API.
     * @param {AxiosInstance} apiClient - Axios instance for API handle.
     * @param {string} encryptionKey - Encryption key for handle request/response encryption/decryption.
     * @param {boolean} logging - Enable/Disable API logs.
     * @param {string} responseType - Data convert to JSON/Stringify enable/disable.
     */
    constructor(apiClient: AxiosInstance, encryptionKey: string, logging: boolean, responseType: string) {
        this.api = apiClient;
        this.accessToken = new AccessToken(apiClient);
        this.encryptionKey = encryptionKey;
        this.logging = logging;
        this.responseType = responseType;
    }

     /**
     * Add access token to Request header authorization.
     */
    protected async updateInstance() {
        try {
            if(this.api.defaults.headers.common.Authorization) {
                delete this.api.defaults.headers.common.Authorization;
            }

            let token = await this.accessToken.getToken();
            logger(this.logging, logTitles.accessTokenSuccess, token);
            this.api.defaults.headers.common.Authorization = `Bearer ${token.data[0]}`;
        } catch (error: any) {
            throw error;
        }
    }

    /**
     * POST API Request.
     * @param {string} url - The url for POST API request.
     * @param {any} payload - The payload for POST API request.
     * @returns {Promise<ResponseEntity>} A promise that resolves to the POST API request.
     */
    protected async _post(url: string, payload?: any): Promise<ResponseEntity> {
        try {
            await this.updateInstance();

            let encryptedPayload;
            if(payload) {
                encryptedPayload = await encryptPayload(this.encryptionKey, payload, this.logging);
            }

            const response: any = await this.api.post<ResponseEntity>(url, encryptedPayload ? encryptedPayload : {});

            if(response?.data?.errors) {
                return sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(response.data.errors));
            }
            
            const decryptedResponse = await decryptPayload(this.encryptionKey, response, this.responseType, this.logging);

            return decryptedResponse;
        } catch (error: any) {
            const data = error?.response?.data?.errors || error?.data?.errors || (error?.message && [{errorCode: "400", errorMessage: error.message}]) || [{errorCode: "500", errorMessage: errors.apiError}];

            throw sbiException(400, error?.exceptionCode || exceptions.invalidResponseErrorCode, error?.exceptionMessage || exceptions.invalidResponseErrorMessage, JSON.stringify(data));
        }
    }

    /**
     * GET API Request.
     * @param {string} url - The url for GET API request.
     * @returns {Promise<ResponseEntity>} A promise that resolves to the GET API request.
     */
    protected async _get(url: string): Promise<ResponseEntity> {
        try {
            await this.updateInstance();

            const response: any = await this.api.get<ResponseEntity>(url);

            if(response?.data?.errors) {
                return sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(response.data.errors));
            }

            const decryptedResponse = await decryptPayload(this.encryptionKey, response, this.responseType, this.logging);
            
            return decryptedResponse;
        } catch (error: any) {
            const data =  error?.response?.data?.errors || error?.data?.errors || (error?.message && [{errorCode: "400", errorMessage: error.message}]) || [{errorCode: "500", errorMessage: errors.apiError}];

            throw sbiException(400, error?.exceptionCode || exceptions.invalidResponseErrorCode, error?.exceptionMessage || exceptions.invalidResponseErrorMessage, JSON.stringify(data));
        }
    }
}
