/**
 * This class handles access token /token/access API endpoint.
 */
import { AxiosInstance } from 'axios';
import axiosRetry from 'axios-retry';
import { exceptions } from '../utils/constants';
import { endpoints } from '../utils/endpoints';

export class AccessToken {
  private api: AxiosInstance;

  /**
   * Creates an instance of the Access Token.
   * @param {AxiosInstance} apiClient - Axios instance for API handle.
   */
  constructor(apiClient: AxiosInstance) {
    this.api = apiClient;
  }

  /**
   * Get access token.
   * @returns {Promise<any>} A promise that resolves to the created customer entity.
   */
  async getToken(): Promise<any> {
    try {
      axiosRetry(this.api, {
        retries: 2,
        retryDelay: (retryCount: number) => {
          return axiosRetry.exponentialDelay(retryCount * 1000); // Exponential backoff
        },
        retryCondition: (error: any) => {
          return axiosRetry.isNetworkOrIdempotentRequestError(error) || error.response?.status == 500;
        },
      });

      const response = await this.api.post(endpoints.accessToken);
      if(response?.data?.errors) {
          throw response;
      }
      return response.data;
    } catch (error: any) {
      error.exceptionCode = exceptions.ioErrorCode;
      error.exceptionMessage = exceptions.accessTokenErrorMessage;
      throw error;
    }
  }
}
