/**
 * Enable/Disable console logs
 * @param {boolean} isLog - Enable/Disable logs.
 * @param {string} title - Log title.
 * @param {any} data - log data.
 */
export const logger = (isLog: boolean, title: string, data: any) => {
    //@ts-ignore
    // Fortify SCA Suppress: PrivacyViolation (Debug Only)
    isLog && console.debug(title, data);
}

/**
 * Exception handling
 * @param {number} errorCode - Error codes.
 * @param {string} errorMessage - Error message.
 * @param {any} data - Error data.
 */
export const sbiException = (errorCode: number, statusCode: number, errorMessage: string, data: any = "") => {
    return {
        status: 0,
        errors: [{
            errorCode: errorCode,
            errorMessage: `Status Code: ${statusCode}\nServer response: ${errorMessage}${data}`
        }]
    }
}
