/**
 * Crypto resource.
 * This class handles all interactions with the /crypto API endpoint.
 */
import { logger, sbiException } from '../utils/helper';
import { errors, exceptions, logTitles } from '../utils/constants';
import { decrypt, encrypt } from '../utils/crypto/aes';

export class Crypto {
    private encryptionKey: string;
    protected logging: boolean;
    protected responseType: string;

    /**
     * Creates an instance of the Crypto.
     * @param {string} encryptionKey - Encryption key for handle request/response encryption/decryption.
     * @param {boolean} logging - Enable/Disable API logs.
     * @param {string} responseType - Data convert to JSON/Stringify enable/disable.
     */
    constructor(encryptionKey: string, logging: boolean, responseType: string) {
        this.encryptionKey = encryptionKey;
        this.logging = logging;
        this.responseType = responseType;
    }

    /**
     * Encrypt payload.
     * @param {any} payload - The data for encryption.
     * @returns {Promise<any>} A promise that resolves to the encrypted payload.
     */
    async encrypt(payload: any): Promise<any> {
        if (!payload) {
            logger(this.logging, logTitles.payloadEncryptError, errors.payloadEncryptError);
            const data = { error: errors.payloadEncryptError };
            throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
        }
        
        try {
            const encryptedPayload = await encrypt(this.encryptionKey, (typeof payload !== "string")?JSON.stringify(payload):payload);
            logger(this.logging, logTitles.payloadEncryptSuccess, encryptedPayload);
            return encryptedPayload;
        } catch (error: any) {
            logger(this.logging, logTitles.payloadEncryptError, error);
            const data = (error?.message && [{errorCode: "400", errorMessage: error.message}]) || [{errorCode: "500", errorMessage: errors.apiError}];
            throw sbiException(400, error?.exceptionCode || exceptions.invalidResponseErrorCode, error?.exceptionMessage || exceptions.invalidResponseErrorMessage, JSON.stringify(data));
        }
    }

    /**
     * Decrypt payload.
     * @param {any} payload - The data for decryption.
     * @returns {Promise<any>} A promise that resolves to the decrypted payload.
     */
    async decrypt(payload: any): Promise<any> {
        if (!payload) {
            logger(this.logging, logTitles.payloadDecryptError, errors.payloadDecryptError);
            const data = { error: errors.payloadDecryptError };
            throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
        }

        try {
            let decryptedPayload = await decrypt(this.encryptionKey, payload);
            logger(this.logging, logTitles.payloadDecryptSuccess, decryptedPayload);
            return (this.responseType == "STRING")?decryptedPayload:JSON.parse(decryptedPayload);
        } catch (error: any) {
            logger(this.logging, logTitles.payloadDecryptError, error);
            const data = (error?.message && [{errorCode: "400", errorMessage: error.message}]) || [{errorCode: "500", errorMessage: errors.apiError}];
            throw sbiException(400, error?.exceptionCode || exceptions.invalidResponseErrorCode, error?.exceptionMessage || exceptions.invalidResponseErrorMessage, JSON.stringify(data));
        }
    }
    
    /**
     * Decode payload.
     * @param {any} payload - The data for decoding.
     * @returns {Promise<any>} A promise that resolves to the decoded payload.
     */
    async decodeCallback(payload: any): Promise<any> {
        if (!payload) {
            logger(this.logging, logTitles.decodeCallbackError, errors.decodeCallbackError);
            const data = { error: errors.decodeCallbackError };
            throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
        }

        try {
            // let uriBase64decoded = atob(decodeURIComponent(decodeURIComponent(payload))).replace(/\"/g,'');
            // Custom decode callback
            let uriBase64decoded = payload.replace(/-/g, '+').replace(/_/g, '/');

            while (uriBase64decoded.length % 4) {
                uriBase64decoded += '=';
            }

            uriBase64decoded = atob(uriBase64decoded).replace(/\"/g,'');
            
            let decryptedPayload = await decrypt(this.encryptionKey, uriBase64decoded);
            logger(this.logging, logTitles.decodeCallbackSuccess, decryptedPayload);
            return (this.responseType == "STRING")?decryptedPayload:JSON.parse(decryptedPayload);
        } catch (error: any) {
            logger(this.logging, logTitles.decodeCallbackError, error);
            const data = (error?.message && [{errorCode: "400", errorMessage: error.message}]) || [{errorCode: "500", errorMessage: errors.apiError}];
            throw sbiException(400, error?.exceptionCode || exceptions.invalidResponseErrorCode, error?.exceptionMessage || exceptions.invalidResponseErrorMessage, JSON.stringify(data));
        }
    }
}
