/**
 * Main SDK entry point.
 * This file exports the main SDK class that users will instantiate.
 */
import axios, { AxiosInstance } from 'axios';
import { SDKCredentials } from './types';
import { Customer } from './modules/Customer';
import { Order } from './modules/Order';
import { Refund } from './modules/Refund';
import { Crypto } from './modules/Crypto';
import { logger, sbiException } from './utils/helper';
import { errors, exceptions, logTitles } from './utils/constants';

/**
 * The main class for the SBI ePay SDK.
 * Users will instantiate this class to interact with the API.
 */
export class SBIEPayClient {
  // The internal Axios instance for making API requests
  private apiClient: AxiosInstance;
  public customer: Customer;
  public order: Order;
  public refund: Refund;
  public crypto: Crypto;

  /**
   * Creates an instance of the SBIEPayClient SDK.
   * @param {SDKCredentials} credentials - The credentials for the SDK.
   * @param {'LIVE' | 'SANDBOX'} environment - SDK environment.
   * @param {boolean} logging - Enable/Disable API logs.
   * @param {string} responseType - Data convert to JSON/Stringify enable/disable.
   */
  constructor(credentials: SDKCredentials, environment: 'LIVE' | 'SANDBOX', logging: boolean = false, responseType: string = 'JSON') {
    logger(logging, "SDK config", credentials);

    if (!credentials.apiKey || !credentials.apiSecret) {
      logger(logging, logTitles.sbiEpayClientInitializationError, errors.keySecretError);
      const data = {error: errors.keySecretError};
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    if (!credentials.encryptionKey) {
      logger(logging, logTitles.sbiEpayClientInitializationError, errors.encryptionKeyError);
      const data = {error: errors.encryptionKeyError};
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    if (!environment || (environment !== 'LIVE' && environment !== 'SANDBOX')) {
      logger(logging, logTitles.sbiEpayClientInitializationError, errors.environmentError);
      const data = {error: errors.environmentError};
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    if (typeof logging != "boolean") {
      logger(logging, logTitles.sbiEpayClientInitializationError, errors.loggingError);
      const data = {error: errors.loggingError};
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    if (!responseType || (responseType !== 'JSON' && responseType !== 'STRING')) {
      logger(logging, logTitles.sbiEpayClientInitializationError, errors.responseTypeError);
      const data = {error: errors.responseTypeError};
      throw sbiException(400, exceptions.errorResponseCode, exceptions.invalidResponseErrorMessage, JSON.stringify(data));
    }

    this.apiClient = axios.create({
      baseURL: environment == 'LIVE' ? process.env.LIVE_API_BASE_URL : process.env.SANDBOX_API_BASE_URL,
      headers: {
        'Content-Type': 'application/json',
        'Merchant-API-Key-Id': credentials.apiKey,
        'Merchant-API-Key-Secret': credentials.apiSecret
      },
    });

    this.customer = new Customer(this.apiClient, credentials.encryptionKey, logging, responseType);
    this.order = new Order(this.apiClient, credentials.encryptionKey, logging, responseType);
    this.refund = new Refund(this.apiClient, credentials.encryptionKey, logging, responseType);
    this.crypto = new Crypto(credentials.encryptionKey, logging, responseType);
  }
}

// Also export all types for consumers of the library
export * from './types';
